:root {
  --bg: #282c34;
  --bg-alt: #2c313c;
  --bg-ui: #21252b;
  --fg: #abb2bf;
  --fg-muted: #828997;
  --od-border: #3e4451;
  --input-bg: var(--bg);
  --red: #e06c75;
  --green: #98c379;
  --yellow: #e5c07b;
  --blue: #61afef;
  --purple: #c678dd;
  --cyan: #56b6c2;
  --orange: #d19a66;
  --selection: #404859;
  --accent: #528cff;
  --accent-muted: rgba(82,140,255,0.25);
  --header-width: 0 !important;
  --header-resizer-width: 0 !important;
}
#header {
  position: fixed !important;
  top: 0;
  height: 100vh !important;
  z-index: 99999 !important;
  display: block !important;
  background: var(--bg-ui);
  box-sizing: border-box !important;
  overflow: visible !important;
  width: 450px !important;
/* --- LEFT SIDEBAR LOGIC --- */
  left: 0;
  right: auto;
  border-right: 1px solid var(--selection);
}
body:has(#header) {
  padding-left: 450px !important;
  padding-right: 0 !important;
}
#header.sticky {
  box-shadow: none;
}
body {
  background-color: var(--bg);
  color: var(--fg);
}
.tab body {
  border-color: var(--od-border);
}
#header-resizer {
  color: var(--od-border);
}
#message-box-title {
  color: var(--fg);
  background: var(--bg-alt);
}
h2 {
  color: var(--blue) !important;
}
select,
input:not([type]),
input[type="number"],
input[type="search"],
input[type="text"],
input[type="url"] {
  border: 1px solid var(--od-border);
}
.entry.odd {
  background-color: rgba(44,49,60,0.4);
}
button {
  color: var(--fg) !important;
  background: var(--bg-alt) !important;
  border: 1px solid var(--od-border) !important;
  transition: all 0.2s;
}
button:hover {
  border-color: var(--accent) !important;
  background: var(--selection) !important;
}
button:disabled {
  color: var(--fg-muted) !important;
  opacity: 0.5;
}
.active #filters-stats,
.dirty #save-button,
.dirty #save-button + button {
  background-color: var(--accent) !important;
  border-color: var(--accent) !important;
  color: var(--bg) !important;
}
.applies-to input,
.applies-to select,
input[type="text"],
input[type="radio"] {
  background: var(--bg-alt);
  border: 1px solid var(--od-border);
  color: var(--fg);
}
.add-applies-to i,
.remove-applies-to i {
  color: var(--fg-muted);
}
.svg-icon {
  fill: var(--fg-muted);
}
.svg-icon:hover {
  fill: var(--accent);
}
.onoffswitch input:checked + span {
  background-color: var(--accent-muted);
}
.onoffswitch input:checked + span::before {
  background-color: var(--accent);
}
footer {
  background-color: var(--bg-ui);
  border-color: var(--od-border);
}
.CodeMirror {
  background: var(--bg) !important;
  color: var(--fg) !important;
  font-size: 12px;
}
.CodeMirror-gutters {
  background: var(--bg) !important;
  border-right: 1px solid var(--od-border) !important;
}
.CodeMirror-linenumber {
  color: var(--fg-muted) !important;
}
.CodeMirror-cursor {
  border-left: 1px solid var(--accent) !important;
}
.CodeMirror-activeline-background {
  background: var(--bg-alt) !important;
}
.CodeMirror-matchingbracket {
  color: var(--cyan) !important;
  text-decoration: underline !important;
}
.CodeMirror-selected,
.CodeMirror-line::selection,
.CodeMirror-line > span::selection,
.CodeMirror-line > span > span::selection {
  background: var(--selection) !important;
}
.cm-comment {
  color: var(--fg-muted) !important;
}
.cm-keyword {
  color: var(--purple) !important;
}
.cm-builtin {
  color: var(--cyan) !important;
}
.cm-string {
  color: var(--green) !important;
}
.cm-number,
.cm-atom {
  color: var(--orange) !important;
}
.cm-variable {
  color: var(--fg) !important;
}
.cm-variable-2 {
  color: var(--fg) !important;
}
.cm-variable-3,
.cm-type {
  color: var(--purple) !important;
}
.cm-def {
  color: var(--blue) !important;
}
.cm-property {
  color: var(--cyan) !important;
}
.cm-operator {
  color: var(--cyan) !important;
}
.cm-tag {
  color: var(--red) !important;
}
.cm-attribute {
  color: var(--orange) !important;
}
.cm-qualifier {
  color: var(--orange) !important;
}
.cm-error {
  background: var(--red) !important;
  color: var(--fg) !important;
}
[data-cmd="delete"] {
  border-color: var(--red) !important;
}
#menu.delete header {
  background: rgba(224,108,117,0.25) !important;
}

