/* ==UserStyle==
@name           Stylus OneDark Unified (UI + Editor)
@namespace      github.com/openstyles/stylus
@version        20260515.15.57
@description    OneDark combined theme: full interface, editor, and sidebar auto-hiding
@author         Octopus
@license        CC-BY-4.0
@preprocessor   stylus
@var            select   sidebar_mode  "Sidebar Mode" {
    "Auto-hide*": "auto",
    "Always visible": "visible"
}
@var            select   sidebar_pos   "Sidebar Position" {
    "Left*": "left",
    "Right": "right"
}
@var            text     sidebar_width "Sidebar Width" 350px
==/UserStyle== */

@-moz-document regexp("^\\w+-extension://[^/]+/edit.*"),
url-prefix("moz-extension://"),
url-prefix("chrome-extension://") {
    /***
     If you want:
     - to disable the sidebar's auto-hide feature,
     - adjust its width,
     - or move it to the right side,
     you can do so in the settings by clicking the gear icon next to the style's name
               (..)
              ((()))
    ***/
    :root {
        --bg: #282c34;
        --bg-alt: #2c313c;
        --bg-ui: #21252b;
        --fg: #abb2bf;
        --fg-muted: #828997;
        --od-border: #3e4451;
        --input-bg: var(--bg);

        --red: #e06c75;
        --green: #98c379;
        --yellow: #e5c07b;
        --blue: #61afef;
        --purple: #c678dd;
        --cyan: #56b6c2;
        --orange: #d19a66;
        --selection: #404859;
        --accent: #528cff;
        --accent-muted: rgba(82, 140, 255, 0.25);

        --header-width: 0 !important;
        --header-resizer-width: 0 !important;
    }

    /* ============================================================
       1. SIDEBAR CONFIGURATION (Responsive Hover/Touch Trigger)
       ============================================================ */
    #header {
        position: fixed !important;
        top: 0;
        height: 100vh !important;
        z-index: 99999 !important;
        display: block !important;
        background: var(--bg-ui);
        box-sizing: border-box !important;
        overflow: visible !important; 
        width: unquote("" + sidebar_width) !important;

        /* --- LEFT SIDEBAR LOGIC --- */
        if sidebar_pos == "left" {
            left: 0;
            right: auto;
            border-right: 1px solid var(--selection);

            if sidebar_mode == "auto" {
                transform: translateX(-100%);
                transition: transform .15s ease-in-out !important; 

                & > * { 
                    opacity: 0; 
                    transition: opacity .2s ease-in-out;
                    pointer-events: none;
                }

                /* Default button: optimized for desktop (narrow, 13px) */
                &::after {
                    content: "〉";
                    position: absolute;
                    top: 50%;
                    right: -13px; /* Pushed out by the new width */
                    transform: translateY(-50%);
                    width: 13px;  /* Visible 13px bar */
                    height: 75px;
                    background: var(--bg-alt);
                    border: 1px solid var(--od-border);
                    border-left: none;
                    border-radius: 0 4px 4px 0;
                    color: var(--accent);
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    font-size: 11px;
                    text-indent: 0; /* Centered arrow */
                    font-weight: bold;
                    cursor: pointer;
                    pointer-events: auto !important;
                    box-shadow: 2px 0 5px rgba(0,0,0,0.2);
                }

                /* Enlarge the touch area only on mobile/touch screens */
                @media (pointer: coarse) {
                    &::after {
                        right: -30px;
                        width: 30px;
                        font-size: 14px;
                        text-indent: 0;
                        border-radius: 0 8px 8px 0;
                        box-shadow: 4px 0 10px rgba(0,0,0,0.3);
                    }
                }

                /* Smooth slide-out on desktop (mouse hover) */
                &:hover {
                    transform: translateX(0) !important;
                    transition: transform .22s ease-out !important; 

                    & > * { 
                        opacity: 1; 
                        pointer-events: auto;
                    }
                    &::after {
                        right: 0;
                        content: "〈";
                        border-left: 1px solid var(--od-border);
                        border-right: none;
                        border-radius: 4px 0 0 4px;
                        text-indent: 0;
                        box-shadow: -4px 0 10px rgba(0,0,0,0.3);

                        @media (pointer: coarse) {
                            border-radius: 8px 0 0 8px;
                        }
                    }
                }

                /* Fast response to touch on mobile devices */
                &:active {
                    transform: translateX(0) !important;
                    transition: transform 0s !important; 
                    & > * { opacity: 1; pointer-events: auto; }
                }
            }
        }

        /* --- RIGHT SIDEBAR LOGIC --- */
        if sidebar_pos == "right" {
            right: 0;
            left: auto;
            border-left: 1px solid var(--selection);

            if sidebar_mode == "auto" {
                transform: translateX(100%);
                transition: transform .15s ease-in-out !important; 

                & > * { 
                    opacity: 0; 
                    transition: opacity .2s ease-in-out;
                    pointer-events: none;
                }

                /* Default button: optimized for desktop (narrow, 13px) */
                &::after {
                    content: "〈";
                    position: absolute;
                    top: 50%;
                    left: -13px;
                    transform: translateY(-50%);
                    width: 13px;
                    height: 75px;
                    background: var(--bg-alt);
                    border: 1px solid var(--od-border);
                    border-right: none;
                    border-radius: 4px 0 0 4px;
                    color: var(--accent);
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    font-size: 11px;
                    text-indent: 0;
                    font-weight: bold;
                    cursor: pointer;
                    pointer-events: auto !important;
                    box-shadow: -2px 0 5px rgba(0,0,0,0.2);
                }

                /* Enlarge the touch area only on mobile/touch screens */
                @media (pointer: coarse) {
                    &::after {
                        left: -42px;
                        width: 42px;
                        font-size: 14px;
                        text-indent: 0;
                        border-radius: 8px 0 0 8px;
                        box-shadow: -4px 0 10px rgba(0,0,0,0.3);
                    }
                }

                &:hover {
                    transform: translateX(0) !important;
                    transition: transform .22s ease-out !important;

                    & > * { 
                        opacity: 1; 
                        pointer-events: auto;
                    }
                    &::after {
                        left: 0;
                        content: "〉";
                        border-right: 1px solid var(--od-border);
                        border-left: none;
                        border-radius: 0 4px 4px 0;
                        text-indent: 0;
                        box-shadow: 4px 0 10px rgba(0,0,0,0.3);

                        @media (pointer: coarse) {
                            border-radius: 0 8px 8px 0;
                        }
                    }
                }

                &:active {
                    transform: translateX(0) !important;
                    transition: transform 0s !important;
                    & > * { opacity: 1; pointer-events: auto; }
                }
            }
        }
    }

    /* Dynamic page padding adjustment - restricted to protect popup views */
    if sidebar_mode == "visible" {
        if sidebar_pos == "left" {
            body:has(#header) {
                padding-left: unquote("" + sidebar_width) !important;
                padding-right: 0 !important;
            }
        }
        if sidebar_pos == "right" {
            body:has(#header) {
                padding-right: unquote("" + sidebar_width) !important;
                padding-left: 0 !important;
            }
        }
    } else {
        body {
            padding-left: 0 !important;
            padding-right: 0 !important;
        }
    }

    #header.sticky {
        box-shadow: none;
    }

    /* ============================================================
       2. USER INTERFACE (Main UI & Popups)
       ============================================================ */
    body {
        background-color: var(--bg);
        color: var(--fg);
    }

    .tab body {
        border-color: var(--od-border);
    }

    #header-resizer {
        color: var(--od-border);
    }

    #message-box-title {
        color: var(--fg);
        background: var(--bg-alt);
    }

    h2 {
        color: var(--blue) !important;
    }

    select,
    input:not([type]),
    input[type="number"],
    input[type="search"],
    input[type="text"],
    input[type="url"] {
        border: 1px solid var(--od-border);
    }

    .entry.odd {
        background-color: rgba(44, 49, 60, 0.4);
    }

    /* Buttons and Forms */
    button {
        color: var(--fg) !important;
        background: var(--bg-alt) !important;
        border: 1px solid var(--od-border) !important;
        transition: all 0.2s;
    }

    button:hover {
        border-color: var(--accent) !important;
        background: var(--selection) !important;
    }

    button:disabled {
        color: var(--fg-muted) !important;
        opacity: 0.5;
    }

    .active #filters-stats,
    .dirty #save-button,
    .dirty #save-button + button {
        background-color: var(--accent) !important;
        border-color: var(--accent) !important;
        color: var(--bg) !important;
    }

    .applies-to input,
    .applies-to select,
    input[type="text"],
    input[type="radio"] {
        background: var(--bg-alt);
        border: 1px solid var(--od-border);
        color: var(--fg);
    }
    .add-applies-to i, .remove-applies-to i {
        color: var(--fg-muted);
    }

    /* Icons and Switches */
    .svg-icon {
        fill: var(--fg-muted);
    }
    .svg-icon:hover {
        fill: var(--accent);
    }

    .onoffswitch input:checked + span {
        background-color: var(--accent-muted);
    }
    .onoffswitch input:checked + span::before {
        background-color: var(--accent);
    }

    footer {
        background-color: var(--bg-ui);
        border-color: var(--od-border);
    }

    /* ============================================================
       3. CODEMIRROR EDITOR (Syntax Highlighting)
       ============================================================ */
    .CodeMirror {
        background: var(--bg) !important;
        color: var(--fg) !important;
        font-size: 12px;
    }

    .CodeMirror-gutters {
        background: var(--bg) !important;
        border-right: 1px solid var(--od-border) !important;
    }

    .CodeMirror-linenumber {
        color: var(--fg-muted) !important;
    }

    .CodeMirror-cursor {
        border-left: 1px solid var(--accent) !important;
    }

    .CodeMirror-activeline-background {
        background: var(--bg-alt) !important;
    }

    .CodeMirror-matchingbracket {
        color: var(--cyan) !important;
        text-decoration: underline !important;
    }

    .CodeMirror-selected,
    .CodeMirror-line::selection,
    .CodeMirror-line > span::selection,
    .CodeMirror-line > span > span::selection {
        background: var(--selection) !important;
    }

    /* Syntax Colors */
    .cm-comment { color: var(--fg-muted) !important; }
    .cm-keyword { color: var(--purple)   !important; }
    .cm-builtin { color: var(--cyan)     !important; }
    .cm-string  { color: var(--green)    !important; }
    .cm-number,
    .cm-atom    { color: var(--orange)   !important; }
    .cm-variable { color: var(--fg)       !important; }
    .cm-variable-2 { color: var(--fg)      !important; }
    .cm-variable-3,
    .cm-type    { color: var(--purple)   !important; }
    .cm-def     { color: var(--blue)     !important; }
    .cm-property { color: var(--cyan)     !important; }
    .cm-operator { color: var(--cyan)     !important; }
    .cm-tag     { color: var(--red)      !important; }
    .cm-attribute { color: var(--orange)   !important; }
    .cm-qualifier { color: var(--orange)   !important; }
    .cm-error   { background: var(--red) !important; color: var(--fg) !important; }

    [data-cmd="delete"] {
        border-color: var(--red) !important;
    }
    #menu.delete header {
        background: rgba(224, 108, 117, 0.25) !important;
    }
}
